// Isolation test (OS-12) — construct Dispersion with its declared inputs and nothing else, then
// exercise every public operation. (Generated by new-object.py, rewritten for strict TypeScript - MF-21.)
import { describe, expect, it } from "vitest";
import { asProjection, isUnknown } from "../src/kernel/index.js";
import type { Currency, Unit } from "../src/catalog/index.js";
import { LineageReader } from "../src/facts/index.js";
import { RevisionLog, Samples, type ConditionIdentity } from "../src/condition/index.js";
import { ObservationLedger, score, type Score } from "../src/observation/index.js";
import { Dispersion } from "../src/statistics/index.js";
import { factWorld, never } from "./support/fact-world.js";

const u = "u1" as Unit;
const [c0, c1] = ["c0", "c1"] as unknown as readonly [Currency, Currency];
const X = "x" as ConditionIdentity;

/** Three members of X's sample at c1, each scored on `a`. */
function world() {
  const w = factWorld({ currencies: ["c0", "c1"], invalidations: never });
  const k0 = w.commitAt(u, c0);
  const observations = new ObservationLedger({ record: w.record, components: ["a"] });
  for (const n of [0.2, 0.5, 0.9]) {
    const h = w.record.noise();
    const context = w.draws.recordDraw(u, {}, h, X, h, "ENGINE");
    if (isUnknown(context)) throw new Error("setup");
    const k = w.candidates.appendCandidate({ context, unit: u, currency: c1, condition: X, seed: "s", from: k0 }, "sig", w.record.noise(), "ENGINE");
    if (isUnknown(k)) throw new Error("setup");
    observations.observe(k, { a: { value: score(n) as Score, author: "ENGINE" } }, "ENGINE", w.record.noise());
  }
  const samples = new Samples({ candidates: w.candidates, draws: w.draws, revisions: new RevisionLog({ record: w.record }), lineage: new LineageReader({ record: w.record }) });
  return { ...w, parts: { samples, observations } };
}

describe("Dispersion in isolation", () => {
  it("refuses to construct when an input is missing", () => {
    const { parts } = world();
    for (const missing of Object.keys(parts)) expect(() => new Dispersion({ ...parts, [missing]: undefined } as never), missing).toThrow();
  });

  it("refuses inputs that do not offer the operations it calls (OS-1, declared slots)", () => {
    const { parts } = world();
    for (const slot of Object.keys(parts)) expect(() => new Dispersion({ ...parts, [slot]: {} } as never), slot).toThrow();
  });

  it("of answers differently when samples differs", () => {
    const w = world();
    const h = w.record.noise();
    const empty = { of: () => asProjection("Sample", () => ({ kind: "no-subject" as const })) };
    expect(new Dispersion(w.parts).of(u, c1, X, "a").compute(h)).not.toEqual(new Dispersion({ ...w.parts, samples: empty }).of(u, c1, X, "a").compute(h));
  });

  it("of answers differently when observations differs", () => {
    const w = world();
    const h = w.record.noise();
    expect(new Dispersion(w.parts).of(u, c1, X, "a").compute(h)).not.toEqual(new Dispersion({ ...w.parts, observations: { observationOf: () => ({ kind: "no-subject" }) } }).of(u, c1, X, "a").compute(h));
  });

  it("available answers differently when observations differs", () => {
    const w = world();
    const h = w.record.noise();
    expect(new Dispersion(w.parts).available(u, c1, X, "a", h)).not.toEqual(new Dispersion({ ...w.parts, observations: { observationOf: () => ({ kind: "no-subject" }) } }).available(u, c1, X, "a", h));
  });
});
